{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C47", "C43", "C50", "C51", "C45", "C42"],
  "contradictory_card_ids": ["C62", "C64"],
  "prediction_basis_card_ids": ["C47", "C43", "C50", "C51", "C45", "C42"],
  "claims": [
    {
      "claim": "The query is an eprosartan-like dianionic ARB with two carboxylic acids and a basic imidazole, fully ionized at physiological pH (neutral fraction 0, logD 0.56). The most structurally relevant L4 permeability records, for the dianionic ARB metabolite Exp3174, show very low absorptive Caco-2 Papp (2.50 x 10^-8 cm/s) and high efflux (B-to-A 25.6 x 10^-8 cm/s, ER ~10), with efflux persisting under BCRP/P-gp inhibition.",
      "card_ids": ["C47", "C43", "C50", "C51"]
    },
    {
      "claim": "L5 gut-wall efflux records do not provide query-specific or dianionic-ARB data. The closest ARB record (losartan with quercetin) shows moderate absorptive permeability after P-gp inhibition (PappAB 1.43 x 10^-6 cm/s, ER 1.25), and fimasartan shows high permeability with MRP2 inhibition; these do not overcome the Exp3174 low-permeability evidence for the dianionic query.",
      "card_ids": ["C62", "C64"]
    },
    {
      "claim": "No direct absolute oral bioavailability measurement exists for the query, and the L1 high-F contexts (phenylbutyrate, bumetanide, levodopa, suprofen) are structurally distant from this dianionic ARB, so they do not provide query-specific absorption evidence.",
      "card_ids": ["C01", "C16", "C19"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C62", "C64"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query.",
    "No query-specific Caco-2/MDCK permeability, solubility, dissolution, or gut-wall efflux data are available; L4/L5 records are for analogs (Exp3174, losartan, fimasartan, imatinib, etc.).",
    "No human PK, formulation, or dose data for the query are available; absorption may be formulation-dependent.",
    "No intestinal metabolism data specific to the query are available.",
    "L1 high-F contexts are not structurally matched to the query."
  ],
  "decision_summary": "Kept low: the query is a fully ionized dianionic eprosartan-like ARB; L4 Exp3174 records show very low absorptive permeability and high efflux, and L5 gut-wall efflux records do not provide query-specific or dianionic-ARB evidence that overcomes this. No direct F measurement exists, but the coherent low-permeability/efflux evidence supports F < 20% better than F >= 20%."
}

